const tr=()=>i18n[$('#language').value]||i18n.en;const pt=()=>patientText[$('#language').value]||patientText.en;const vt=()=>voiceText[$('#language').value]||voiceText.en;const gameCopy=g=>(gameText[$('#language').value]||{})[g.id]||[g.title,g.desc,g.instruction];const gameChoices=g=>(choiceText[$('#language').value]||{})[g.id]||g.choices;const routineItems=g=>(choiceText[$('#language').value]||{}).routine||g.items;const domainCopy=d=>(domainText[$('#language').value]||{})[d]||d;function save(){try{localStorage.setItem('smriti:'+storageFamily,JSON.stringify(state))}catch(e){console.warn('Storage save skipped:',e)}}function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2100)}function speak(t){if(!('speechSynthesis'in window))return toast(vt().unavailable);speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.rate=.78;u.lang={en:'en-IN',hi:'hi-IN',as:'as-IN',mni:'mni-IN',kha:'en-IN',lus:'en-IN'}[$('#language').value]||'en-IN';const voices=speechSynthesis.getVoices(),base=u.lang.split('-')[0],match=voices.find(v=>v.lang.toLowerCase().startsWith(base));if(match)u.voice=match;speechSynthesis.speak(u)}
async function syncEmergencyLive(){
  const fid=currentFamilyId||storageFamily||'default';
  try{
    const emRes=await fetch(`/api/emergency?familyId=${encodeURIComponent(fid)}`).then(r=>r.json());
    if(emRes&&emRes.ok&&emRes.emergency&&emRes.emergency.phone){
      const changed=!state.emergency||JSON.stringify(emRes.emergency)!==JSON.stringify(state.emergency);
      if(changed){
        state.emergency=Object.assign({},state.emergency||{},emRes.emergency);
        save();
        renderEmergencyModal();
        if($('#setupEmergencyPhone')&&document.activeElement!==$('#setupEmergencyPhone'))$('#setupEmergencyPhone').value=state.emergency.phone||'';
        if($('#setupEmergencyContact')&&document.activeElement!==$('#setupEmergencyContact'))$('#setupEmergencyContact').value=state.emergency.contactName||'';
        if($('#setupEmergencyAddress')&&document.activeElement!==$('#setupEmergencyAddress'))$('#setupEmergencyAddress').value=state.emergency.address||'';
      }
    }
  }catch(_){}
  if(supabaseClient&&currentPatientId){
    try{
      const {data:pRec}=await supabaseClient.from('patients').select('accessibility').eq('id',currentPatientId).maybeSingle();
      if(pRec?.accessibility?.emergency&&pRec.accessibility.emergency.phone){
        const changed=!state.emergency||JSON.stringify(pRec.accessibility.emergency)!==JSON.stringify(state.emergency);
        if(changed){
          state.emergency=Object.assign({},state.emergency||{},pRec.accessibility.emergency);
          save();
          renderEmergencyModal();
          if($('#setupEmergencyPhone')&&document.activeElement!==$('#setupEmergencyPhone'))$('#setupEmergencyPhone').value=state.emergency.phone||'';
          if($('#setupEmergencyContact')&&document.activeElement!==$('#setupEmergencyContact'))$('#setupEmergencyContact').value=state.emergency.contactName||'';
          if($('#setupEmergencyAddress')&&document.activeElement!==$('#setupEmergencyAddress'))$('#setupEmergencyAddress').value=state.emergency.address||'';
        }
      }
    }catch(_){}
  }
}
