async function changePersonPhoto(id,file){if(!file)return;const person=state.people.find(p=>p.id===id);if(!person)return;const reader=new FileReader();reader.onload=()=>{person.photo=reader.result;save();renderPeople();toast('Photo updated without cropping')};reader.readAsDataURL(file);if(supabaseClient&&currentFamilyId&&currentPatientId){const ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=person.photoPath||`${currentFamilyId}/${crypto.randomUUID()}.${ext}`;const upload=await supabaseClient.storage.from('memory-photos').upload(path,file,{upsert:true});if(upload.error)return toast('Updated locally; cloud upload failed');person.photoPath=path;const {error}=await supabaseClient.from('memory_people').update({photo_path:path}).eq('id',id);if(error)toast('Photo uploaded; database update failed')}}
async function deletePerson(id){if(!confirm('Remove this family memory card?'))return;const person=state.people.find(p=>p.id===id);state.people=state.people.filter(p=>p.id!==id);save();renderPeople();toast('Family memory removed');if(supabaseClient&&currentFamilyId&&person){if(person.photoPath)await supabaseClient.storage.from('memory-photos').remove([person.photoPath]);await supabaseClient.from('memory_people').delete().eq('id',id)}}

function evaluateAdaptive(){const ss=(state.sessions||[]).slice(0,6),avgHints=ss.length?(ss.reduce((a,s)=>a+(s.hints||0),0)/ss.length):0,avgLatency=ss.length?(ss.reduce((a,s)=>a+(s.response||0),0)/ss.length):0,hour=new Date().getHours(),isEvening=hour>=17,needsScaffolding=avgHints>=0.8||avgLatency>11||isEvening,pill=$('#adaptiveStatusText');if(pill){if(isEvening&&needsScaffolding)pill.textContent='Gentle Evening Mode: Relaxed 2-Choice Pacing';else if(needsScaffolding)pill.textContent='Adaptive Scaffolding: 2-Choice Pacing Active';else pill.textContent='Adaptive Engine: Optimal Comfort';}return{needsScaffolding,avgHints,avgLatency,isEvening};}
