async function loadRemote(){const [people,reminders,sessions,patientRec]=await Promise.all([supabaseClient.from('memory_people').select('*').eq('patient_id',currentPatientId),supabaseClient.from('reminders').select('*').eq('patient_id',currentPatientId).eq('enabled',true),supabaseClient.from('game_sessions').select('*').eq('patient_id',currentPatientId).order('created_at',{ascending:false}).limit(50),supabaseClient.from('patients').select('accessibility').eq('id',currentPatientId).maybeSingle()]);if(patientRec?.data?.accessibility?.emergency){state.emergency=patientRec.data.accessibility.emergency;save();renderEmergencyModal();if($('#setupEmergencyPhone'))$('#setupEmergencyPhone').value=state.emergency.phone||'';if($('#setupEmergencyContact'))$('#setupEmergencyContact').value=state.emergency.contactName||'';if($('#setupEmergencyAddress'))$('#setupEmergencyAddress').value=state.emergency.address||'';}if(Array.isArray(people.data))state.people=await Promise.all(people.data.map(async p=>{const existing=state.people.find(x=>x.id===p.id);let photo=existing?.photo&&existing.photo.startsWith('data:')?existing.photo:'';if(!photo&&p.photo_path){try{const {data}=await supabaseClient.storage.from('memory-photos').createSignedUrl(p.photo_path,3600);if(data?.signedUrl){const res=await fetch(data.signedUrl);if(res.ok){const blob=await res.blob();photo=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(blob)})}else photo=data.signedUrl}}catch(_){photo=existing?.photo||''}}return{id:p.id,name:p.name,relation:p.relationship,clue:p.gentle_clue,photo,photoPath:p.photo_path}}));if(Array.isArray(reminders.data))state.reminders=reminders.data.map(r=>({id:r.id,type:r.type,time:(r.reminder_time||'').slice(0,5),message:r.message}));if(Array.isArray(sessions.data))state.sessions=sessions.data.map(s=>({id:s.id,game:s.game_key,domain:s.domain,accuracy:s.accuracy,response:s.response_seconds,hints:s.hints_used,created_at:s.created_at}));save();renderPeople();renderReminders();renderCare()}
$('#personForm').onsubmit=e=>{e.preventDefault();const f=$('#personPhoto').files[0],record={id:crypto.randomUUID(),name:$('#personName').value,relation:$('#personRelation').value,clue:$('#personClue').value,photo:'',photoPath:null},reader=new FileReader();reader.onload=async()=>{record.photo=reader.result;state.people.unshift(record);save();renderPeople();e.target.reset();toast('Added only to this family space');if(supabaseClient&&currentFamilyId&&currentPatientId){const ext=(f.name.split('.').pop()||'jpg').toLowerCase(),path=`${currentFamilyId}/${crypto.randomUUID()}.${ext}`;const up=await supabaseClient.storage.from('memory-photos').upload(path,f,{upsert:false});if(up.error)return toast('Saved locally; cloud upload failed');const user=(await supabaseClient.auth.getUser()).data.user;const result=await supabaseClient.from('memory_people').insert({family_id:currentFamilyId,patient_id:currentPatientId,name:record.name,relationship:record.relation,gentle_clue:record.clue,photo_path:path,approved_by:user.id}).select('id,photo_path').single();if(result.error)return toast('Photo uploaded; database entry failed');record.id=result.data.id;record.photoPath=result.data.photo_path;save();renderPeople()}};reader.readAsDataURL(f)};
