async function completeLogin(){if(!supabaseClient)return;const {data:{user}}=await supabaseClient.auth.getUser();if(!user)return;let {data:p,error}=await supabaseClient.from('profiles').select('family_id,display_name').eq('id',user.id).maybeSingle();if(error)return authMessage(error.message,true);if(!p){const pending=JSON.parse(localStorage.getItem('smritiPendingFamily')||'null');if(pending&&pending.email===user.email){try{await createFamilyProfile(pending);({data:p,error}=await supabaseClient.from('profiles').select('family_id,display_name').eq('id',user.id).maybeSingle())}catch(e){return authMessage(e.message,true)}}}if(!p){$('#auth').classList.add('hidden');$('#familySignup').classList.add('hidden');$('#onboarding').classList.remove('hidden');$('#newDisplayName').value=user.user_metadata?.display_name||'';return}currentFamilyId=p.family_id;storageFamily=currentFamilyId;state=JSON.parse(localStorage.getItem('smriti:'+storageFamily)||'null')||{people:[],reminders:[],sessions:[]};const [{data:patient,error:patientError},{data:family,error:familyError}]=await Promise.all([supabaseClient.from('patients').select('id,preferred_name,accessibility').eq('family_id',p.family_id).limit(1).maybeSingle(),supabaseClient.from('families').select('name,family_code').eq('id',p.family_id).maybeSingle()]);if(patientError||!patient||familyError)return authMessage(patientError?.message||familyError?.message||'Patient record not configured.',true);currentPatientId=patient.id;currentPatientName=patient.preferred_name||'Patient';if(patient.accessibility?.emergency){state.emergency=patient.accessibility.emergency;save();renderEmergencyModal();if($('#setupEmergencyPhone'))$('#setupEmergencyPhone').value=state.emergency.phone||'';if($('#setupEmergencyContact'))$('#setupEmergencyContact').value=state.emergency.contactName||'';if($('#setupEmergencyAddress'))$('#setupEmergencyAddress').value=state.emergency.address||'';}$('#patientHome .patient-hero h2').textContent=currentPatientName;$('#familyLabel').textContent=family?.name||'Private family';$('#signedInFamilyName').textContent=family?.name||'Private family';$('#signedInFamilyCode').textContent=family?.family_code||String(p.family_id).slice(0,8).toUpperCase();await loadRemote();$('#auth').classList.add('hidden');$('#onboarding').classList.add('hidden');$('#familySignup').classList.add('hidden');$('#roleChooser').classList.remove('hidden')}
